const std = @import("std");
const M = @import("minstd.zig");
const R = @import("road.zig");
const V = @import("vehicles.zig");
const T = @import("signals.zig");
const S = @import("stats.zig");
const Rate = struct { rate: i64, end: usize };
const Source = struct {
    node: []const u8, rates: []const Rate, segment: *R.Segment, queue: std.ArrayList(*V.Vehicle) = .empty, head: usize = 0, queue_start: usize = 0, queue_max: usize = 0,
    fn rate(self: *const Source, step: usize) i64 { for (self.rates) |period| { if (step <= period.end) return period.rate; } return 0; }
};
const Detector = struct { name: []const u8, segment: *R.Segment, cell: i64, width: i64 };
const Diagram = struct { segment: *R.Segment, lane: usize, start: usize, end: usize, lines: S.Lines = .{} };
const Ring = struct { number: usize, length: i64, vmax: i64, warmup: usize, measure: usize, seed: i64, counts: []const usize };
const Interval = struct {
    arrivals: i64 = 0, insertions: i64 = 0, exits: i64 = 0, vehicle_steps: i64 = 0, speed_sum: i64 = 0, passing: []i64, occupancy: []i64, occupancy_speed: []i64,
    fn init(count: usize) Interval { const passing = S.alloc(i64, count); @memset(passing, 0); const occupancy = S.alloc(i64, count); @memset(occupancy, 0); const speeds = S.alloc(i64, count); @memset(speeds, 0); return .{ .passing = passing, .occupancy = occupancy, .occupancy_speed = speeds }; }
};
const Move = struct { vehicle: *V.Vehicle, segment: *R.Segment, cell: i64, speed: i64 = 0, passing: bool = false };
const Route = struct { segments: []const *R.Segment, share: S.Fraction, sink: []const u8 };
fn optional(number: usize) []const u8 { return if (number == 0) "-" else S.fmt("{d}", .{number}); }
fn flag(value: bool) []const u8 { return if (value) "Y" else "N"; }
fn routeText(route: []const *R.Segment, separator: []const u8) []const u8 { const names = S.alloc([]const u8, route.len); for (route, names) |segment, *name| name.* = segment.id; return S.join(names, separator); }
const Simulation = struct {
    segments: std.ArrayList(*R.Segment) = .empty, by_id: std.StringHashMapUnmanaged(*R.Segment) = .empty, junctions: std.ArrayList(*T.Junction) = .empty, incidents: std.ArrayList(*R.Incident) = .empty, stops: std.ArrayList(*R.BusStop) = .empty,
    classes: std.ArrayList(*const V.Class) = .empty, sources: std.ArrayList(*Source) = .empty, sinks: std.ArrayList([]const u8) = .empty,
    steps: usize = 0, dawdle: i64 = 0, dawdle_stopped: i64 = 0, interval_length: usize = 1, bin_width: i64 = 1,
    detectors: std.ArrayList(Detector) = .empty, diagrams: std.ArrayList(*Diagram) = .empty, track_numbers: []const usize = &.{}, tracks: std.AutoHashMapUnmanaged(usize, *S.Lines) = .empty, rings: std.ArrayList(Ring) = .empty,
    rng: M.Minstd = .{ .state = 1 }, vehicles: std.ArrayList(*V.Vehicle) = .empty, intervals: std.ArrayList(*Interval) = .empty, events: S.Lines = .{},
    fn load(self: *Simulation, texts: []const []const u8) void {
        for (texts) |text| { for (S.lines(text)) |line| { const tokens = S.split(line, ' '); const kind = tokens[0]; const fields = tokens[1..];
            if (S.eq(kind, "SEGMENT")) { const count = S.parse(fields[3]); const lanes = S.index(S.parse(fields[4])); const cells = S.alloc(i64, S.index(count) * lanes); @memset(cells, 0); const segment = S.create(R.Segment, .{ .id = fields[0], .start = fields[1], .end = fields[2], .length = count, .lanes = lanes, .limit = S.parse(fields[5]), .index = self.segments.items.len, .cells = cells }); S.append(*R.Segment, &self.segments, segment); self.by_id.put(S.allocator, segment.id, segment) catch @panic("allocation failed");
            } else if (S.eq(kind, "JUNCTION")) { const junction = S.create(T.Junction, T.Junction.init(fields[0], S.parse(fields[1]), fields[2..])); const index = self.junctions.items.len; S.append(*T.Junction, &self.junctions, junction); for (self.segments.items) |segment| { if (S.eq(segment.end, junction.node)) { segment.junction = index; S.append(*R.Segment, &junction.incoming, segment); } }
            } else if (S.eq(kind, "INCIDENT")) { S.append(*R.Incident, &self.incidents, S.create(R.Incident, .{ .segment = self.by_id.get(fields[0]).?, .lane = S.index(S.parse(fields[1])) - 1, .cell = S.parse(fields[2]), .start = S.index(S.parse(fields[3])), .end = S.index(S.parse(fields[4])) }));
            } else if (S.eq(kind, "STOP")) { const segment = self.by_id.get(fields[0]).?; const stop = S.create(R.BusStop, .{ .segment = segment, .cell = S.parse(fields[1]), .dwell = S.parse(fields[2]) }); segment.stop = stop; S.append(*R.BusStop, &self.stops, stop);
            } else if (S.eq(kind, "CLASS")) { S.append(*const V.Class, &self.classes, S.create(V.Class, .{ .name = fields[0], .vmax = S.parse(fields[1]), .weight = S.parse(fields[2]), .overtakes = S.eq(fields[3], "Y"), .stops = S.eq(fields[4], "Y") }));
            } else if (S.eq(kind, "SOURCE")) { const rates = S.alloc(Rate, fields.len - 1); for (fields[1..], rates) |token, *period| { const pair = S.split(token, ':'); period.* = .{ .rate = S.parse(pair[0]), .end = S.index(S.parse(pair[1])) }; } var entry: *R.Segment = undefined; for (self.segments.items) |segment| { if (S.eq(segment.start, fields[0])) { entry = segment; break; } } S.append(*Source, &self.sources, S.create(Source, .{ .node = fields[0], .rates = rates, .segment = entry }));
            } else if (S.eq(kind, "SINK")) { S.append([]const u8, &self.sinks, fields[0]);
            } else if (S.eq(kind, "TURN")) { const segment = self.by_id.get(fields[0]).?; S.append(*R.Turn, &segment.turns, S.create(R.Turn, .{ .target = self.by_id.get(fields[1]).?, .weight = S.parse(fields[2]) }));
            } else if (S.eq(kind, "seed")) { self.rng.state = S.parse(fields[0]);
            } else if (S.eq(kind, "steps")) { self.steps = S.index(S.parse(fields[0]));
            } else if (S.eq(kind, "dawdle")) { self.dawdle = S.parse(fields[0]); self.dawdle_stopped = S.parse(fields[1]);
            } else if (S.eq(kind, "interval")) { self.interval_length = S.index(S.parse(fields[0]));
            } else if (S.eq(kind, "bin")) { self.bin_width = S.parse(fields[0]);
            } else if (S.eq(kind, "detector")) { S.append(Detector, &self.detectors, .{ .name = fields[0], .segment = self.by_id.get(fields[1]).?, .cell = S.parse(fields[2]), .width = S.parse(fields[3]) });
            } else if (S.eq(kind, "diagram")) { S.append(*Diagram, &self.diagrams, S.create(Diagram, .{ .segment = self.by_id.get(fields[0]).?, .lane = S.index(S.parse(fields[1])) - 1, .start = S.index(S.parse(fields[2])), .end = S.index(S.parse(fields[3])) }));
            } else if (S.eq(kind, "track")) { const numbers = S.alloc(usize, fields.len); for (fields, numbers) |token, *number| { number.* = S.index(S.parse(token)); self.tracks.put(S.allocator, number.*, S.create(S.Lines, .{})) catch @panic("allocation failed"); } self.track_numbers = numbers;
            } else { const counts = S.alloc(usize, fields.len - 5); for (fields[5..], counts) |token, *count| count.* = S.index(S.parse(token)); S.append(Ring, &self.rings, .{ .number = self.rings.items.len + 1, .length = S.parse(fields[0]), .vmax = S.parse(fields[1]), .warmup = S.index(S.parse(fields[2])), .measure = S.index(S.parse(fields[3])), .seed = S.parse(fields[4]), .counts = counts }); }
        } }
    }
    fn record(self: *Simulation, step: usize, comptime pattern: []const u8, args: anytype) void { self.events.add("{d:0>4} {s}", .{ step, S.fmt(pattern, args) }); }
    fn current(self: *Simulation) *Interval { return self.intervals.items[self.intervals.items.len - 1]; }
    fn green(self: *const Simulation, segment: *R.Segment, step: usize) bool { return self.junctions.items[segment.junction.?].green(segment.id, step); }
    fn enter(self: *Simulation, vehicle: *V.Vehicle, segment: *R.Segment) void { S.append(*R.Segment, &vehicle.route, segment); segment.entered += 1; if (segment.junction != null) { var weights: [30]i64 = undefined; for (segment.turns.items, 0..) |turn, i| weights[i] = turn.weight; vehicle.turn = segment.turns.items[M.select(weights[0..segment.turns.items.len], self.rng.draw())]; } }
    fn arrive(self: *Simulation, step: usize) void { var weights: [9]i64 = undefined; for (self.classes.items, 0..) |class, i| weights[i] = class.weight; for (self.sources.items, 0..) |source, i| { if (@mod(self.rng.draw(), 1000) < source.rate(step)) { const class = self.classes.items[M.select(weights[0..self.classes.items.len], self.rng.draw())]; const number = self.vehicles.items.len + 1; const vehicle = S.create(V.Vehicle, .{ .number = number, .class = class, .source = i, .arrival = step, .trace = self.tracks.get(number) }); S.append(*V.Vehicle, &self.vehicles, vehicle); S.append(*V.Vehicle, &source.queue, vehicle); self.current().arrivals += 1; } } }
    fn insertVehicles(self: *Simulation, step: usize) void {
        const interval = self.current(); for (self.sources.items) |source| { const segment = source.segment;
            while (source.head < source.queue.items.len) { var best: ?usize = null; var largest: i64 = -1; for (0..segment.lanes) |lane| { const first = segment.first(lane); if (segment.empty(lane, 0) and first > largest) { best = lane; largest = first; } } const lane = best orelse break; const vehicle = source.queue.items[source.head]; source.head += 1; vehicle.place(segment, lane, 0); vehicle.inserted = step; self.enter(vehicle, segment); interval.insertions += 1; }
            const count = source.queue.items.len - source.head; if (count > 0 and source.queue_start == 0) { source.queue_start = step; source.queue_max = 0; } if (source.queue_start != 0) { source.queue_max = @max(source.queue_max, count); if (count == 0) { self.record(step, "QUEUE {s} from {d} max {d}", .{ source.node, source.queue_start, source.queue_max }); source.queue_start = 0; } }
        }
    }
    fn changeLanes(self: *Simulation, temporary: std.mem.Allocator) void {
        const Change = struct { vehicle: *V.Vehicle, lane: usize, kind: usize }; var changes: std.ArrayList(Change) = .empty;
        for (self.segments.items) |segment| { if (segment.lanes < 2) continue; var reserved = [_]bool{false} ** 600;
            for (0..segment.lanes) |lane| { for (segment.row(lane)) |number| { if (number <= 0) continue; const vehicle = self.vehicles.items[S.index(number - 1)]; if (vehicle.dwell > 0) continue; const desired = desiredLane(vehicle); const slot = desired.lane * S.index(segment.length) + S.index(vehicle.cell); if (desired.lane != lane and !reserved[slot]) { reserved[slot] = true; S.tempAppend(Change, &changes, temporary, .{ .vehicle = vehicle, .lane = desired.lane, .kind = desired.kind }); } } }
        }
        for (changes.items) |change| { const vehicle = change.vehicle; const segment = vehicle.segment.?; vehicle.place(segment, change.lane, vehicle.cell); vehicle.lane_changes += 1; segment.changes[change.kind] += 1; }
    }
    fn processingOrder(self: *Simulation, temporary: std.mem.Allocator) []Move { var moves: std.ArrayList(Move) = .empty; for (self.segments.items) |segment| { for (0..segment.lanes) |lane| { var cell = segment.length; while (cell > 0) { cell -= 1; const number = segment.row(lane)[S.index(cell)]; if (number > 0) S.tempAppend(Move, &moves, temporary, .{ .vehicle = self.vehicles.items[S.index(number - 1)], .segment = segment, .cell = cell }); } } } return moves.items; }
    fn determineSpeed(self: *Simulation, vehicle: *V.Vehicle, step: usize) i64 { const segment = vehicle.segment.?; const lane = vehicle.lane; const cell = vehicle.cell; const accelerated = @min(vehicle.speed + 1, vehicle.maxSpeed()); var gap = segment.free(lane, cell, accelerated);
        if (gap < accelerated and cell + gap == segment.length - 1) { if (segment.junction == null) gap = accelerated else if (self.green(segment, step)) { const target = vehicle.turn.?.target; gap += target.free(@min(lane, target.lanes - 1), -1, accelerated - gap); } }
        if (vehicle.headingForStop()) gap = @min(gap, segment.stop.?.cell - cell); var speed = V.randomSlowdown(@min(accelerated, gap), vehicle.speed, self.rng.draw(), self.dawdle, self.dawdle_stopped); if (vehicle.dwell > 0) { speed = 0; vehicle.dwell -= 1; } return speed;
    }
    fn moveVehicles(self: *Simulation, moves: []Move, step: usize) void { for (moves) |*move| { const vehicle = move.vehicle; const segment = move.segment; if (move.cell + move.speed < segment.length) { vehicle.place(segment, vehicle.lane, move.cell + move.speed); } else if (segment.junction == null) { vehicle.leave(); vehicle.exited = step; vehicle.sink = segment.end; self.current().exits += 1; } else move.passing = true; } }
    fn passJunctions(self: *Simulation, moves: []Move) void { for (moves) |*move| { if (!move.passing) continue; const vehicle = move.vehicle; const segment = move.segment; const turn = vehicle.turn.?; const target = turn.target; const lane = @min(vehicle.lane, target.lanes - 1); const overshoot = move.cell + move.speed - segment.length; const cell = @min(overshoot, target.first(lane) - 1); if (cell < overshoot) segment.blocked += 1;
            if (cell >= 0) { vehicle.place(target, lane, cell); move.speed = segment.length - move.cell + cell; segment.passed += 1; turn.vehicles += 1; self.enter(vehicle, target); } else { vehicle.place(segment, vehicle.lane, segment.length - 1); move.speed = segment.length - 1 - move.cell; }
        }
    }
    fn aggregateVehicle(self: *Simulation, move: Move, step: usize) void { const vehicle = move.vehicle; const speed = move.speed; vehicle.steps += 1; vehicle.distance += speed; if (speed == 0) { vehicle.stopped_steps += 1; if (vehicle.speed > 0) vehicle.stop_count += 1; } vehicle.speed = speed; const interval = self.current(); interval.vehicle_steps += 1; interval.speed_sum += speed;
        if (vehicle.headingForStop() and vehicle.lane == 0) { const segment = vehicle.segment.?; const stop = segment.stop.?; if (vehicle.cell == stop.cell) { vehicle.completed |= V.bit(segment.index); vehicle.dwell = stop.dwell; stop.buses += 1; self.record(step, "BUS_STOP {d} {s} cell {d}", .{ vehicle.number, segment.id, stop.cell }); } }
        if (vehicle.trace) |trace| { if (vehicle.segment) |segment| trace.add("{d:0>4} {s} {d} {d} {d}", .{ step, segment.id, vehicle.lane + 1, vehicle.cell, vehicle.speed }) else trace.add("{d:0>4} EXIT {d}", .{ step, vehicle.speed }); }
        for (self.detectors.items, 0..) |detector, i| { if (move.segment == detector.segment and move.cell < detector.cell and (vehicle.segment != detector.segment or vehicle.cell >= detector.cell)) interval.passing[i] += 1; }
    }
    fn aggregateState(self: *Simulation, step: usize) void { const interval = self.current(); for (self.detectors.items, 0..) |detector, i| { for (0..detector.segment.lanes) |lane| { for (detector.segment.row(lane)[S.index(detector.cell)..S.index(detector.cell + detector.width)]) |number| { if (number > 0) { interval.occupancy[i] += 1; interval.occupancy_speed[i] += self.vehicles.items[S.index(number - 1)].speed; } } } }
        for (self.segments.items) |segment| { var count: i64 = 0; var speeds: i64 = 0; var queued: i64 = 0; for (segment.cells) |number| { if (number > 0) { const speed = self.vehicles.items[S.index(number - 1)].speed; count += 1; speeds += speed; if (speed == 0) queued += 1; } } segment.vehicle_sum += count; segment.speed_sum += speeds; segment.max_vehicles = @max(segment.max_vehicles, count);
            if (segment.junction != null) { const is_green = self.green(segment, step); if (is_green) segment.green_steps += 1; segment.queue_sum += queued; segment.max_queue = @max(segment.max_queue, queued); if (step < self.steps and queued > 0 and is_green and !self.green(segment, step + 1)) segment.failures += 1; }
        }
        for (self.diagrams.items) |diagram| { if (step >= diagram.start and step <= diagram.end) { const segment = diagram.segment; const light: u8 = if (segment.junction == null) 'E' else if (self.green(segment, step)) 'G' else 'R'; diagram.lines.add("{d:0>4} {s} {c}", .{ step, segment.cellsText(diagram.lane, self.vehicles.items), light }); } }
    }
    fn run(self: *Simulation) void { for (1..self.steps + 1) |step| { var temporary = std.heap.ArenaAllocator.init(S.backing); defer temporary.deinit();
            for (self.incidents.items) |incident| { if (incident.update(step)) |event| self.record(step, "{s} {s} lane {d} cell {d}", .{ event, incident.segment.id, incident.lane + 1, incident.cell }); }
            if ((step - 1) % self.interval_length == 0) S.append(*Interval, &self.intervals, S.create(Interval, Interval.init(self.detectors.items.len)));
            self.arrive(step); self.insertVehicles(step); self.changeLanes(temporary.allocator()); const moves = self.processingOrder(temporary.allocator()); for (moves) |*move| move.speed = self.determineSpeed(move.vehicle, step); self.moveVehicles(moves, step); self.passJunctions(moves); for (moves) |move| self.aggregateVehicle(move, step); self.aggregateState(step);
        }
        for (self.sources.items) |source| { if (source.queue_start != 0) self.record(self.steps, "QUEUE {s} from {d} max {d} open", .{ source.node, source.queue_start, source.queue_max }); }
    }
    fn enumerateRoutes(self: *Simulation, segment: *R.Segment) []const Route { if (segment.junction == null) { const route = S.alloc(*R.Segment, 1); route[0] = segment; const result = S.alloc(Route, 1); result[0] = .{ .segments = route, .share = S.Fraction.init(1, 1), .sink = segment.end }; return result; }
        var total: i64 = 0; for (segment.turns.items) |turn| total += turn.weight; var result: std.ArrayList(Route) = .empty;
        for (segment.turns.items) |turn| { for (self.enumerateRoutes(turn.target)) |route| { const sequence = S.alloc(*R.Segment, route.segments.len + 1); sequence[0] = segment; @memcpy(sequence[1..], route.segments); S.append(Route, &result, .{ .segments = sequence, .share = route.share.mul(S.Fraction.init(turn.weight, total)), .sink = route.sink }); } } return result.items;
    }
    fn selected(self: *const Simulation, class: ?*const V.Class, source: ?usize, only_exited: bool) []const *V.Vehicle { var result: std.ArrayList(*V.Vehicle) = .empty; for (self.vehicles.items) |vehicle| { if (only_exited and vehicle.exited == 0) continue; if (class) |kind| { if (vehicle.class != kind) continue; } if (source) |index| { if (vehicle.source != index) continue; } S.append(*V.Vehicle, &result, vehicle); } return result.items; }
    fn spacetimeLines(self: *const Simulation) S.Lines { var result: S.Lines = .{}; for (self.diagrams.items) |diagram| { result.add("DIAGRAM {s} lane {d} steps {d}-{d}", .{ diagram.segment.id, diagram.lane + 1, diagram.start, diagram.end }); result.extend(diagram.lines); } return result; }
    fn detectorLines(self: *const Simulation) S.Lines { var result: S.Lines = .{}; result.write("detector,interval,flow,density,speed"); for (self.detectors.items, 0..) |detector, i| { const capacity = S.int(self.interval_length) * detector.width * S.int(detector.segment.lanes); for (self.intervals.items, 1..) |interval, number| { const occupancy = interval.occupancy[i]; result.add("{s},{d},{d},{s},{s}", .{ detector.name, number, interval.passing[i], S.dec(occupancy, capacity, 4), S.dec(interval.occupancy_speed[i], occupancy, 2) }); } } return result; }
    fn travelTimeLines(self: *Simulation) S.Lines { var result: S.Lines = .{}; for (self.classes.items) |class| result.extend(travelBlock(S.fmt("CLASS {s}", .{class.name}), self.selected(class, null, true), self.bin_width)); result.extend(travelBlock("ALL", self.selected(null, null, true), self.bin_width));
        for (self.sources.items, 0..) |source, i| { const group = self.selected(null, i, true); result.add("SOURCE {s} exited {d}", .{ source.node, group.len }); const routes = self.enumerateRoutes(source.segment);
            for (routes) |route| { var matched: std.ArrayList(*V.Vehicle) = .empty; for (group) |vehicle| { if (std.mem.eql(*R.Segment, vehicle.route.items, route.segments)) S.append(*V.Vehicle, &matched, vehicle); } result.add("  ROUTE {s} expected {s} {s}", .{ routeText(route.segments, ","), route.share.text(), outcomeText(matched.items, group.len) }); }
            for (self.sinks.items) |sink| { var share = S.Fraction.init(0, 1); var present = false; for (routes) |route| { if (S.eq(route.sink, sink)) { share = share.add(route.share); present = true; } } if (!present) continue; var matched: std.ArrayList(*V.Vehicle) = .empty; for (group) |vehicle| { if (S.eq(vehicle.sink, sink)) S.append(*V.Vehicle, &matched, vehicle); } result.add("  SINK {s} expected {s} {s}", .{ sink, share.text(), outcomeText(matched.items, group.len) }); }
        } return result;
    }
    fn classStatsLines(self: *const Simulation) S.Lines { var result: S.Lines = .{}; for (self.classes.items) |class| { const heading = S.fmt("CLASS {s} vmax {d} weight {d} overtake {s} stops {s}", .{ class.name, class.vmax, class.weight, flag(class.overtakes), flag(class.stops) }); result.extend(classBlock(heading, self.selected(class, null, false))); } result.extend(classBlock("ALL", self.vehicles.items)); return result; }
    fn networkStatsLines(self: *const Simulation) S.Lines {
        var result: S.Lines = .{}; for (self.segments.items) |segment| { const capacity = S.int(self.steps) * segment.length * S.int(segment.lanes); result.add("SEGMENT {s} {s} {s} length {d} lanes {d} limit {d} entered {d} mean_vehicles {s} density {s} mean_speed {s} max_vehicles {d} changes {d}/{d}/{d}", .{ segment.id, segment.start, segment.end, segment.length, segment.lanes, segment.limit, segment.entered, S.dec(segment.vehicle_sum, S.int(self.steps), 3), S.dec(segment.vehicle_sum, capacity, 4), S.dec(segment.speed_sum, segment.vehicle_sum, 2), segment.max_vehicles, segment.changes[0], segment.changes[1], segment.changes[2] }); }
        for (self.junctions.items) |junction| { result.extend(junction.planLines()); for (junction.incoming.items) |segment| { result.add("  IN {s} green {d} passed {d} blocked {d} max_queue {d} mean_queue {s} failures {d}", .{ segment.id, segment.green_steps, segment.passed, segment.blocked, segment.max_queue, S.dec(segment.queue_sum, S.int(self.steps), 3), segment.failures }); for (segment.turns.items) |turn| result.add("    TURN {s} weight {d} vehicles {d}", .{ turn.target.id, turn.weight, turn.vehicles }); } }
        for (self.stops.items) |stop| result.add("STOP {s} cell {d} dwell {d} buses {d}", .{ stop.segment.id, stop.cell, stop.dwell, stop.buses });
        for (self.incidents.items) |incident| { const active = if (incident.active_start == 0) "none" else S.fmt("{d}-{d}", .{ incident.active_start, incident.active_end }); result.add("INCIDENT {s} lane {d} cell {d} planned {d}-{d} active {s}", .{ incident.segment.id, incident.lane + 1, incident.cell, incident.start, incident.end, active }); } return result;
    }
    fn timelineLines(self: *const Simulation) S.Lines { var result: S.Lines = .{}; result.write("interval,arrived,inserted,exited,in_network,queued,mean_speed"); var arrived: i64 = 0; var inserted: i64 = 0; var exited: i64 = 0; for (self.intervals.items, 1..) |interval, i| { arrived += interval.arrivals; inserted += interval.insertions; exited += interval.exits; result.add("{d},{d},{d},{d},{d},{d},{s}", .{ i, interval.arrivals, interval.insertions, interval.exits, inserted - exited, arrived - inserted, S.dec(interval.speed_sum, interval.vehicle_steps, 2) }); } return result; }
