    if (vehicle.headingForStop()) return if (lane >= 1 and segment.safe(lane - 1, cell)) .{ .lane = lane - 1, .kind = 1 } else .{ .lane = lane };
    if (vehicle.class.overtakes and lane + 1 < segment.lanes and here < want and segment.free(lane + 1, cell, top + 1) > here and segment.safe(lane + 1, cell)) return .{ .lane = lane + 1, .kind = 0 };
