fn lessTime(_: void, a: i64, b: i64) bool { return a < b; }
fn travelBlock(heading: []const u8, vehicles: []const *V.Vehicle, width: i64) S.Lines { var result: S.Lines = .{}; if (vehicles.len == 0) { result.add("{s} exited 0", .{heading}); return result; } const times = S.alloc(i64, vehicles.len); var total: i64 = 0; for (vehicles, times) |vehicle, *time| { time.* = vehicle.travelTime(); total += time.*; } std.mem.sort(i64, times, {}, lessTime); result.add("{s} exited {d} min {d} p50 {d} p90 {d} max {d} mean {s}", .{ heading, times.len, times[0], S.percentile(times, 50), S.percentile(times, 90), times[times.len - 1], S.dec(total, S.int(times.len), 2) }); result.extend(S.histogram(times, width)); return result; }
