fn ringLess(positions: []const i64, a: usize, b: usize) bool { return positions[a] > positions[b]; }
fn runRing(ring: Ring, count: usize, dawdle: i64, stopped: i64) i64 {
    var rng: M.Minstd = .{ .state = ring.seed }; var positions: [1000]i64 = undefined; var speeds = [_]i64{0} ** 1000; var updated: [1000]i64 = undefined; var order: [1000]usize = undefined; for (0..count) |i| { positions[i] = @divFloor(S.int(i) * ring.length, S.int(count)); order[i] = i; } var total: i64 = 0;
