    const reports = [_]S.Lines{ simulation.spacetimeLines(), simulation.detectorLines(), simulation.travelTimeLines(), simulation.classStatsLines(), simulation.networkStatsLines(), simulation.timelineLines(), simulation.trackLines(), simulation.fundamentalLines(), simulation.events }; const names = [_][]const u8{ "spacetime.txt", "detectors.csv", "travel_times.txt", "class_stats.txt", "network_stats.txt", "timeline.csv", "tracks.txt", "fundamental.csv", "events.txt" }; try dir.createDirPath(init.io, "output"); for (names, reports) |name, report| try dir.writeFile(init.io, .{ .sub_path = S.fmt("output/{s}", .{name}), .data = report.content() });
}

