pub const Segment = struct {
    id: []const u8, start: []const u8, end: []const u8, length: i64, lanes: usize, limit: i64, index: usize, cells: []i64,
    junction: ?usize = null, turns: std.ArrayList(*Turn) = .empty, stop: ?*BusStop = null,
